public class ExchangeRateClient {

    public class ExchangeRateException extends Exception {}

    /**
     * Fetches live FX rates from the provider via Named Credential.
     * 
     * @param baseCurrency The base currency code (e.g., 'EUR').
     * @param quoteCurrencies A set of quote currency codes (e.g., {'USD', 'GBP'}).
     * @return A Map of normalized currency codes to their respective exchange rates.
     * @throws ExchangeRateException If validation fails, callout fails, or response is invalid.
     */
    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // 1. Normalise and Validate Inputs
        String normalizedBase = (baseCurrency == null) ? '' : baseCurrency.trim().toUpperCase();

        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('The quote currencies set must not be null or empty.');
        }

        Set<String> normalizedQuotes = new Set<String>();
        for (String q : quoteCurrencies) {
            String normalizedQ = (q == null) ? '' : q.trim().toUpperCase();
            if (!isValidCurrencyCode(normalizedQ)) {
                throw new ExchangeRateException('Invalid quote currency code detected: ' + q);
            }
            normalizedQuotes.add(normalizedQ);
        }

        if (!isValidCurrencyCode(normalizedBase)) {
            throw new ExchangeRateException('Invalid base currency code detected: ' + baseCurrency);
        }

        // 2. Prepare Request
        // Construct query parameters. The order in the set doesn't matter for the API.
        String symbolsParam = String.join(new List<String>(normalizedQuotes), ',');
        String endpoint = 'callout:FB_Exchange_Rates/v1/latest?base=' + normalizedBase + '&symbols=' + symbolsParam;

        HttpRequest req = new HttpRequest();
        req.setEndpoint(endpoint);
        req.setMethod('GET');
        req.setHeader('Accept', 'application/json');

        // 3. Execute Callout with Retry Logic
        Http http = new Http();
        HttpResponse res = http.send(req);

        // If status is 503, retry once with an identical request
        if (res.getStatusCode() == 503) {
            res = http.send(req);
        }

        // 4. Validate Response Status
        if (res.getStatusCode() != 200) {
            throw new ExchangeRateException('API returned error status: ' + res.getStatusCode());
        }

        // 5. Parse and Process Response
        try {
            Map<String, Object> responseBody = (Map<String, Object>) JSON.deserializeUntyped(res.getBody());
            Map<String, Object> ratesMap = (Map<String, Object>) responseBody.get('rates');

            if (ratesMap == null) {
                throw new ExchangeRateException('The API response did not contain a "rates" object.');
            }

            Map<String, Decimal> result = new Map<String, Decimal>();
            for (String q : normalizedQuotes) {
                if (!ratesMap.containsKey(q) || ratesMap.get(q) == null) {
                    throw new ExchangeRateException('The requested rate for ' + q + ' was not found in the response.');
                }

                // Convert rate to Decimal. JSON.deserializeUntyped often parses numbers as Double/Integer.
                Object rateValue = ratesMap.get(q);
                result.put(q, Decimal.valueOf(String.valueOf(rateValue)));
            }

            return result;
        } catch (Exception e) {
            // If it is already our custom exception, just rethrow it.
            if (e instanceof ExchangeRateException) {
                throw e;
            }
            // Otherwise, wrap the parsing error.
            throw new ExchangeRateException('Failed to parse the exchange rate response: ' + e.getMessage());
        }
    }

    /**
     * Validates that a currency code is exactly three uppercase letters A-Z.
     */
    private static Boolean isValidCurrencyCode(String code) {
        if (code == null || code.length() != 3) {
            return false;
        }
        // Ensure code consists only of A-Z
        return Pattern.compile('^[A-Z]{3}$').matcher(code).matches();
    }
}
