public with sharing class ContactDomainService {
    /**
     * Groups contacts of the provided accounts by their email domain.
     *
     * @param accountIds The set of Account IDs to filter contacts by.
     * @return A map where keys are lower-cased email domains and values are lists of matching Contacts.
     */
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> domainMap = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return domainMap;
        }

        // Query contacts belonging to the provided account IDs.
        // We filter for Email != null in the query to reduce the number of records processed.
        // Each contact in the result will have Id, Email, and AccountId populated as per the SELECT clause.
        for (Contact con : [
            SELECT Id, Email, AccountId 
            FROM Contact 
            WHERE AccountId IN :accountIds 
            AND Email != null
        ]) {
            String email = con.Email;

            // Validate that the email string is not blank and contains the '@' delimiter.
            if (String.isNotBlank(email) && email.contains('@')) {
                // Extract the part after the '@' and convert to lower case.
                String domain = email.substringAfter('@').toLowerCase();

                // Ensure the domain part is not an empty string (e.g., in case of 'user@').
                if (String.isNotBlank(domain)) {
                    if (!domainMap.containsKey(domain)) {
                        domainMap.put(domain, new List<Contact>());
                    }
                    domainMap.get(domain).add(con);
                }
            }
        }

        return domainMap;
    }
}
