        mocks.verify(uowMock.registerDirty(opp3), 0);
        mocks.verify(uowMock.registerDirty(opp4), 0);
        mocks.verify(uowMock.registerDirty(opp5), 0);
        mocks.verify(uowMock.registerDirty(opp6), 0);

        // Verify commitWork was called exactly once
        mocks.verify(uowMock.commitWork(), 1);
    }

