public class Opportunities extends fflib_SObjectDomain {

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public SObject construct() {
            return new Opportunity();
        }
    }

    public Opportunities(List<SObject> sObjects) {
        super(sObjects);
    }

    public override void onBeforeInsert(List<SObject> sObjects) {
        validateAmountNotNegative(sObjects);
    }

    public override void onBeforeUpdate(List<SObject> sObjects) {
        validateAmountNotNegative(sObjects);
        validateAmountChangedOnWonOpportunity(sObjects);
    }

    /**
     * Rule 1: On insert and on update, Amount must not be negative.
     */
    private void validateAmountNotNegative(List<SObject> sObjects) {
        for (SObject so : sObjects) {
            Opportunity opp = (Opportunity)so;
            if (opp.Amount != null && opp.Amount < 0) {
                error('Amount cannot be negative.', opp, 'Amount');
            }
        }
    }

    /**
     * Rule 2: On update, an opportunity whose stage was already Closed Won before the update 
     * cannot have its Amount changed.
     */
    private void validateAmountChangedOnWonOpportunity(List<SObject> sObjects) {
        Map<Id, SObject> oldMap = (Map<Id, SObject>) getTriggerRequest().oldMap;
        for (SObject so : sObjects) {
            Opportunity opp = (Opportunity)so;
            Opportunity oldOpp = (Opportunity)oldMap.get(opp.Id);

            if (oldOpp.StageName == 'Closed Won' && opp.Amount != oldOpp.Amount) {
                error('Amount cannot change on a won opportunity.', opp, 'Amount');
            }
        }
    }
}
