public class ContactsSelector extends fflib_SObjectSelector {

    /**
     * Returns a list of Contacts with the given IDs.
     * Uses the selector's field list and default security/ordering settings.
     * 
     * @param contactIds The set of Contact IDs to query.
     * @return A list of Contact records. Returns an empty list if contactIds is null or empty.
     */
    public List<Contact> selectById(Set<Id> contactIds) {
        if (contactIds == null || contactIds.isEmpty()) {
            return new List<Contact>();
        }

        // Call the base selector's selectById which uses the QueryFactory to execute the query.
        // We then cast the resulting SObjects to Contacts. 
        // We iterate and cast individually to avoid the "Invalid cast from List<SObject> to List<Contact>" error.
        List<SObject> results = super.selectById(contactIds);
        List<Contact> contacts = new List<Contact>();
        for (SObject s : results) {
            contacts.add((Contact)s);
        }
        return contacts;
    }

    public override SObjectType getSObjectType() {
        return Contact.SObjectType;
    }

    public override List<SObjectField> getSObjectFieldList() {
        return new List<SObjectField> {
            Contact.Id,
            Contact.FirstName,
            Contact.LastName,
            Contact.Email,
            Contact.Title,
            Contact.AccountId
        };
    }
}
