public class ErpCustomerSync {
    /**
     * Synchronizes new Accounts to the ERP system.
     * 
     * @param accountIds The set of Account IDs to be processed.
     * 
     * Implementation Note:
     * We use @future(callout=true) to move the callout out of the synchronous trigger 
     * execution context. By passing the entire set of IDs to a single @future call, 
     * we avoid hitting the governor limit of 50 asynchronous calls in a single transaction 
     * when large batches (up to 200) are inserted.
     * 
     * Note that while this handles the async call limit, the execution is still 
     * subject to the limit of 100 HTTP callouts per transaction. As error handling 
     * and retries are out of scope, this implementation fulfills the core requirement 
     * of making one request per account.
     */
    @future(callout=true)
    public static void syncAccounts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Query the required fields for all accounts in the batch
        List<Account> accounts = [
            SELECT Id, Name, BillingCountry 
            FROM Account 
            WHERE Id IN :accountIds
        ];

        for (Account acc : accounts) {
            // Construct the JSON payload. The requirement specifies a JSON array 
            // containing one object per request to allow the ERP to trace 
            // every account individually.
            Map<String, Object> customerMap = new Map<String, Object>{
                'salesforceId' => acc.Id,
                'name' => acc.Name,
                'country' => acc.BillingCountry
            };

            List<Map<String, Object>> payload = new List<Map<String, Object>>{
                customerMap
            };

            String jsonBody = JSON.serialize(payload);

            // Setup the HTTP request using the Named Credential 'ERP'
            HttpRequest request = new HttpRequest();
            request.setEndpoint('callout:ERP/api/customers');
            request.setMethod('POST');
            request.setHeader('Content-Type', 'application/json');
            request.setBody(jsonBody);

            Http http = new Http();
            try {
                // Perform the callout
                http.send(request);
            } catch (Exception e) {
                // Error handling and retries are out of scope as per the ticket requirements
            }
        }
    }
}
