trigger OpportunityTrigger on Opportunity (after insert, after update) {
    Set<Id> accountIdsToProcess = new Set<Id>();

    for (Opportunity opp : Trigger.new) {
        if (Trigger.isInsert) {
            // For new opportunities, we need to recalculate the associated account
            if (opp.AccountId != null) {
                accountIdsToProcess.add(opp.AccountId);
            }
        } else if (Trigger.isUpdate) {
            Opportunity oldOpp = Trigger.oldMap.get(opp.Id);

            // Scenario 1: The Opportunity moved to a different Account
            if (opp.AccountId != oldOpp.AccountId) {
                if (oldOpp.AccountId != null) {
                    accountIdsToProcess.add(oldOpp.AccountId);
                }
                if (opp.AccountId != null) {
                    accountIdsToProcess.add(opp.AccountId);
                }
            } 
            // Scenario 2: The Account is the same, but relevant fields changed
            else if (opp.AccountId != null && (opp.Amount != oldOpp.Amount || opp.StageName != oldOpp.StageName)) {
                accountIdsToProcess.add(opp.AccountId);
            }
        }
    }

    if (!accountIdsToProcess.isEmpty()) {
        // We pass the entire set to a single asynchronous call to ensure bulk-safety
        AccountRatingService.recalculate(accountIdsToProcess);
    }
}
