public class AccountRatingService {
    /**
     * Recalculates the Rating for accounts based on their open opportunity pipeline.
     * 
     * @param accountIds Set of Account IDs to recalculate
     */
    @future
    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Query the accounts and their related open opportunities
        // IsClosed = false is the standard way to identify 'open' opportunities
        List<Account> accountsToUpdate = [
            SELECT Id, Rating, 
                (SELECT Id, Amount FROM Opportunities WHERE IsClosed = false)
            FROM Account 
            WHERE Id IN :accountIds
        ];

        List<Account> updates = new List<Account>();

        for (Account acc : accountsToUpdate) {
            String targetRating = 'Cold';
            Boolean hasOpenOpp = false;
            Boolean hasHotOpp = false;

            for (Opportunity opp : acc.Opportunities) {
                hasOpenOpp = true;
                if (opp.Amount != null && opp.Amount >= 100000) {
                    hasHotOpp = true;
                    // We can break early once we find a Hot opportunity
                    break;
                }
            }

            if (hasOpenOpp) {
                targetRating = hasHotOpp ? 'Hot' : 'Warm';
            } else {
                targetRating = 'Cold';
            }

            // Only add to the update list if the rating has actually changed
            // This optimizes DML and prevents unnecessary trigger recursions/audit logs
            if (acc.Rating != targetRating) {
                acc.Rating = targetRating;
                updates.add(acc);
            }
        }

        if (!updates.isEmpty()) {
            update updates;
        }
    }
}
