public class AccountCountrySync {
    /**
     * Synchronizes Account BillingCountry to Contact MailingCountry when the country changes.
     * 
     * @param newMap The map of new Account versions in the trigger context.
     * @param oldMap The map of old Account versions in the trigger context.
     */
    public static void handleAfterUpdate(Map<Id, Account> newMap, Map<Id, Account> oldMap) {
        Set<Id> changedAccountIds = new Set<Id>();
        Map<Id, String> accountToNewCountry = new Map<Id, String>();
        Map<Id, String> accountToOldCountry = new Map<Id, String>();

        // 1. Identify accounts where BillingCountry has changed
        for (Account acc : newMap.values()) {
            Account oldAcc = oldMap.get(acc.Id);
            if (acc.BillingCountry != oldAcc.BillingCountry) {
                changedAccountIds.add(acc.Id);
                accountToNewCountry.put(acc.Id, acc.BillingCountry);
                accountToOldCountry.put(acc.Id, oldAcc.BillingCountry);
            }
        }

        // If no country changes were detected in this batch, exit early
        if (changedAccountIds.isEmpty()) {
            return;
        }

        // 2. Fetch and process related contacts
        // Note: I have modified the approach to query only the contacts related to the changed accounts.
        // Querying [SELECT Id, AccountId, MailingCountry FROM Contact] on a 2.3M record org 
        // would trigger a 'Too many query rows' exception and exceed Heap limits.
        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact con : [SELECT Id, AccountId, MailingCountry 
                            FROM Contact 
                            WHERE AccountId IN :changedAccountIds]) {

            String oldCountry = accountToOldCountry.get(con.AccountId);
            String newCountry = accountToNewCountry.get(con.AccountId);

            // Only update if MailingCountry is currently blank OR matches the previous BillingCountry
            if (con.MailingCountry == null || con.MailingCountry == oldCountry) {
                con.MailingCountry = newCountry;
                contactsToUpdate.add(con);
            }
        }

        // 3. Perform DML update
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
