import { LightningElement, api } from 'lwc';

export default class AccountContactList extends LightningElement {
    @api contacts;

    /**
     * Returns true if contacts is not null/undefined and has at least one entry.
     */
    get hasContacts() {
        return this.contacts && this.contacts.length > 0;
    }

    /**
     * Returns the contact count text: "1 contact" or "n contacts".
     */
    get contactCountText() {
        const count = this.contacts ? this.contacts.length : 0;
        return count === 1 ? '1 contact' : `${count} contacts`;
    }

    /**
     * Returns a copy of the contacts array sorted by Name ascending.
     */
    get sortedContacts() {
        if (!this.contacts) {
            return [];
        }
        // Create a shallow copy to avoid mutating the original array passed by the parent
        return [...this.contacts].sort((a, b) => {
            return a.Name.localeCompare(b.Name);
        });
    }
}
