import { LightningElement, wire } from 'lwc';
import { subscribe, unsubscribe, MessageContext, APPLICATION_SCOPE } from 'lightning/messageService';
import ACCOUNT_SELECTED_CHANNEL from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    selectedAccountId = null;
    subscription = null;

    @wire(MessageContext)
    messageContext;

    /**
     * Subscribes to the message channel using the wired MessageContext.
     * The wired function ensures we have the context before attempting to subscribe.
     */
    @wire(MessageContext)
    wiredContext(context) {
        if (context && !this.subscription) {
            this.subscription = subscribe(
                context,
                ACCOUNT_SELECTED_CHANNEL,
                (message) => {
                    // Update selectedAccountId based on the incoming message.
                    // If recordId is null or missing, clear the selection.
                    this.selectedAccountId = message?.recordId ? message.recordId : null;
                },
                { scope: APPLICATION_SCOPE }
            );
        }
    }

    /**
     * Cleans up the subscription when the component is removed from the DOM.
     */
    disconnectedCallback() {
        if (this.subscription) {
            unsubscribe(this.subscription);
            this.subscription = null;
        }
    }

    /**
     * Handles the clear action by publishing a null recordId to the channel.
     */
    handleClear(event) {
        if (event.target.dataset.action === 'clear') {
            publish(this.messageContext, ACCOUNT_SELECTED_CHANNEL, { recordId: null });
        }
    }
}
