import { LightningElement, api } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { deleteRecord } from 'lightning/uiRecordApi';
import LightningConfirm from 'lightning/confirm';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    _opportunities = [];
    displayedOpportunities = [];

    @api
    get opportunities() {
        return this._opportunities;
    }
    set opportunities(value) {
        this._opportunities = value;
        // Initialize the local display array with a copy of the passed opportunities
        this.displayedOpportunities = value ? [...value] : [];
    }

    columns = [
        { label: 'Name', fieldName: 'Name' },
        { label: 'Stage', fieldName: 'StageName' },
        { label: 'Amount', fieldName: 'Amount', type: 'currency' },
        {
            type: 'action',
            typeAttributes: {
                rowActions: [
                    { label: 'View', name: 'view' },
                    { label: 'Edit', name: 'edit' },
                    { label: 'Delete', name: 'delete' }
                ]
            }
        }
    ];

    async handleRowAction(event) {
        const actionName = event.detail.action.name;
        const row = event.detail.row;

        switch (actionName) {
            case 'view':
                this[NavigationMixin.Navigate]({
                    type: 'standard__recordPage',
                    attributes: {
                        recordId: row.Id,
                        actionName: 'view'
                    }
                });
                break;

            case 'edit':
                this[NavigationMixin.Navigate]({
                    type: 'standard__recordPage',
                    attributes: {
                        recordId: row.Id,
                        actionName: 'edit'
                    }
                });
                break;

            case 'delete':
                const confirmed = await LightningConfirm.open({
                    message: 'Are you sure you want to delete this opportunity?',
                    label: 'Confirm Delete'
                });

                if (confirmed) {
                    try {
                        await deleteRecord(row.Id);
                        // Update local state to remove row without mutating parent array
                        this.displayedOpportunities = this.displayedOpportunities.filter(item => item.Id !== row.Id);
                        this.dispatchEvent(
                            new ShowToastEvent({
                                title: 'Opportunity deleted',
                                variant: 'success'
                            })
                        );
                    } catch (error) {
                        this.dispatchEvent(
                            new ShowToastEvent({
                                title: 'Delete failed',
                                message: error.body?.message || error.message,
                                variant: 'error'
                            })
                        );
                    }
                }
                break;

            default:
                break;
        }
    }
}
