     * @param {MouseEvent} event 
     */
    handleAction(event) {
        const action = event.target.dataset.action;
        if (action === 'reset') {
            this.handleReset();
        } else if (action === 'submit') {
            this.handleSubmit();
        }
    }

    /**
     * Calls reset() on all child line item editors and clears error messages.
     */
    handleReset() {
        const editors = this.template.querySelectorAll('c-line-item-editor');
        editors.forEach(editor => {
            editor.reset();
        });
        this.showError = false;
    }

    /**
     * Validates all child line item editors.
     * If all are valid, dispatches a 'submit' event with the current values.
     * If any are invalid, displays an error message.
     */
    handleSubmit() {
        const editors = this.template.querySelectorAll('c-line-item-editor');
        let allValid = true;
        const results = [];

        // Iterate through all editors to ensure validation is triggered for every line
        editors.forEach(editor => {
            if (!editor.validate()) {
                allValid = false;
            }
            // Collect the value from every editor in display order
            results.push(editor.getValue());
        });

        if (allValid) {
            this.showError = false;
            this.dispatchEvent(new CustomEvent('submit', {
                detail: { lines: results }
            }));
        } else {
            this.showError = true;
        }
    }
}
