import { LightningElement } from 'lwc';
import register from '@salesforce/apex/RegistrationController.register';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleInputChange(event) {
        const field = event.target.dataset.field;
        const value = event.target.value;
        if (field) {
            this[field] = value;
        }
    }

    async handleRegister() {
        const emailInput = this.template.querySelector('lightning-input[data-field="email"]');
        const fullNameInput = this.template.querySelector('lightning-input[data-field="fullName"]');
        const companyInput = this.template.querySelector('lightning-input[data-field="company"]');

        // 1. Validate email domain
        const invalidDomains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];
        const domain = this.email.split('@')[1]?.toLowerCase();

        if (domain && invalidDomains.includes(domain)) {
            emailInput.setCustomValidity('Use your work email address.');
        } else {
            emailInput.setCustomValidity('');
        }

        // 2. Call reportValidity() on every input to show all errors at once
        const inputs = [fullNameInput, emailInput, companyInput];
        let allValid = true;
        inputs.forEach(input => {
            if (input && !input.reportValidity()) {
                allValid = false;
            }
        });

        // 3. If all valid, call register imperative Apex
        if (allValid) {
            try {
                await register({
                    fullName: this.fullName,
                    email: this.email,
                    company: this.company
                });
                this.dispatchEvent(new ShowToastEvent({
                    variant: 'success',
                    title: 'Registered'
                }));
            } catch (error) {
                this.dispatchEvent(new ShowToastEvent({
                    variant: 'error',
                    title: 'Registration failed',
                    message: error.body ? error.body.message : error.message
                }));
            }
        }
    }
}
