import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    _heading = '';
    @api get heading() {
        return this._heading ? this._heading.toUpperCase() : '';
    }
    @api set heading(value) {
        this._heading = value;
    }

    _tasks = [];
    @api get tasks() {
        return this._tasks;
    }
    @api set tasks(value) {
        // Create a deep copy of the array and its objects to ensure the component 
        // works on its own copy and never modifies the parent's data.
        this._tasks = value ? value.map(task => ({ ...task })) : [];
        this.items = [...this._tasks];
    }

    items = [];
    newLabel = '';
    nextId = 1;

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const trimmedLabel = this.newLabel ? this.newLabel.trim() : '';
        if (!trimmedLabel) {
            return;
        }

        const newTask = { 
            id: `new-${this.nextId++}`, 
            label: trimmedLabel, 
            done: false 
        };

        // Update items with a new array to maintain reactivity and immutability
        this.items = [...this.items, newTask];
        this.newLabel = '';

        // Dispatch the event with the label that was actually added
        this.dispatchEvent(new CustomEvent('taskadded', { 
            detail: { label: trimmedLabel } 
        }));
    }

    handleToggle(event) {
        const taskId = event.target.dataset.id;
        const isChecked = event.target.checked;

        // Use map to create a new array and a new object for the modified task,
        // ensuring we don't mutate the existing objects in the array.
        this.items = this.items.map(task => {
            if (task.id === taskId) {
                return { ...task, done: isChecked };
            }
            return task;
        });
    }
}
