public class GauAllocationService {

    /**
     * Exception class for GauAllocationService errors.
     */
    public class AllocationException extends Exception {}

    /**
     * Allocates an Opportunity's amount across multiple General Accounting Units (GAUs) based on percentages.
     * Replaces existing allocations for the given opportunity.
     * 
     * @param opportunityId The Id of the Opportunity to allocate.
     * @param percentByGauId A map where keys are GAU Ids and values are percentages (e.g., 60 for 60%).
     * @return A list of the newly inserted npsp__Allocation__c records.
     * @throws AllocationException if validation fails.
     */
    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        // 1. Validate the map is not null or empty
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('The allocation map cannot be null or empty.');
        }

        // 2. Validate percentages (not null, > 0) and calculate sum
        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            Decimal pct = percentByGauId.get(gauId);
            if (pct == null || pct <= 0) {
                throw new AllocationException('All percentages must be greater than 0.');
            }
            totalPercent += pct;
        }

        // 3. Validate total percentage does not exceed 100
        if (totalPercent > 100) {
            throw new AllocationException('Total percentage cannot exceed 100%.');
        }

        // 4. Validate GAUs exist and are active
        Set<Id> gauIds = percentByGauId.keySet();
        Map<Id, npsp__General_Accounting_Unit__c> gauMap = new Map<Id, npsp__General_Accounting_Unit__c>([
            SELECT Id, npsp__IsActive__c 
            FROM npsp__General_Accounting_Unit__c 
            WHERE Id IN :gauIds
        ]);

        for (Id gauId : gauIds) {
            if (!gauMap.containsKey(gauId)) {
                throw new AllocationException('One or more provided GAUs were not found.');
            }
            if (!gauMap.get(gauId).npsp__IsActive__c) {
                throw new AllocationException('One or more GAUs are inactive.');
            }
        }

        // 5. Perform data changes
        // Note: Deleting and inserting is wrapped in the current transaction. 
        // If an error occurs, the entire operation rolls back.

        // Delete existing allocations for this specific opportunity
        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id 
            FROM npsp__Allocation__c 
            WHERE npsp__Opportunity__c = :opportunityId
        ];

        if (!existingAllocations.isEmpty()) {
            delete existingAllocations;
        }

        // Prepare new allocations
        // By setting npsp__Percentage__c, NPSP's internal logic handles the 
        // automatic recalculation of npsp__Amount__c when the Opportunity amount changes.
        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : gauIds) {
            newAllocations.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percentage__c = percentByGauId.get(gauId)
            ));
        }

        if (!newAllocations.isEmpty()) {
            insert newAllocations;
        }

        return newAllocations;
    }
}
