public class HouseholdService {
    /**
     * Creates a single NPSP Household Account and assigns all provided contacts to it.
     * 
     * @param members A list of new Contact records (without Id or AccountId).
     * @return The Id of the newly created Household Account.
     * @throws IllegalArgumentException if the members list is null or empty.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('The members list cannot be null or empty.');
        }

        // 1. Retrieve the Household Account Record Type.
        // NPSP uses 'Household_Account' as the standard DeveloperName for its household record type.
        // We use the schema method to avoid hard-coding IDs.
        Schema.RecordTypeInfo rtInfo = Schema.SObjectType.Account.getRecordTypeInfosByDeveloperName()
            .get('Household_Account');

        if (rtInfo == null) {
            throw new IllegalArgumentException('The NPSP Household Account record type was not found in this org.');
        }

        Id householdRtId = rtInfo.getRecordTypeId();

        // 2. Create the Household Account.
        // The Account.Name field is a required field in Salesforce. 
        // Since the requirement is to "not set the account name yourself" and let NPSP handle it,
        // we provide a minimal placeholder name (using the first member's Last Name if available)
        // to satisfy the database requirement. NPSP's automation triggers will 
        // automatically overwrite this name with the correct household name upon contact insertion.
        String placeholderName = (members[0].LastName != null && members[0].LastName != '') 
            ? members[0].LastName 
            : 'Household Account';

        Account householdAcc = new Account(
            RecordTypeId = householdRtId,
            Name = placeholderName
        );

        // Insert the account first so we have an Id to link the contacts to.
        insert householdAcc;

        // 3. Link all contacts to the new household account.
        // We iterate through the list to assign the newly created AccountId.
        for (Contact member : members) {
            member.AccountId = householdAcc.Id;
        }

        // 4. Insert the contacts.
        // Once the contacts are inserted, NPSP's automation logic (via triggers) 
        // will:
        // - Calculate and update the Household Account Name.
        // - Identify the first contact in the household and set it as the Primary Contact.
        insert members;

        return householdAcc.Id;
    }
}
