public class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    /**
     * Adds or updates partial soft credits for fundraisers on opportunities.
     * 
     * @param requests A list of SoftCreditRequest objects.
     * @throws SoftCreditException if validation fails (primary contact, invalid amount, etc.)
     */
    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            if (req.opportunityId != null) {
                oppIds.add(req.opportunityId);
            }
            if (req.contactId != null) {
                contactIds.add(req.contactId);
            }
        }

        // 1. Query Opportunities to validate amounts and primary contacts
        // SOQL Query 1
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>([
            SELECT Id, npsp__Primary_Contact__c, Amount 
            FROM Opportunity 
            WHERE Id IN :oppIds
        ]);

        // Validation (Must happen before any DML)
        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppMap.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found.');
            }
            if (req.amount == null || req.amount <= 0 || req.amount > opp.Amount) {
                throw new SoftCreditException('Invalid amount for Opportunity ' + req.opportunityId);
            }
            if (req.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException('Contact ' + req.contactId + ' is the primary contact for Opportunity ' + req.opportunityId);
            }
        }

        // 2. Query existing OpportunityContactRoles
        // SOQL Query 2
        Map<String, OpportunityContactRole> ocrMap = new Map<String, OpportunityContactRole>();
        for (OpportunityContactRole ocr : [
            SELECT Id, ContactId, OpportunityId, Role 
            FROM OpportunityContactRole 
            WHERE ContactId IN :contactIds AND OpportunityId IN :oppIds
        ]) {
            // Using a separator to ensure unique composite keys
            ocrMap.put(ocr.OpportunityId + '-' + ocr.ContactId, ocr);
        }

        // 3. Query existing Partial Soft Credits linked to existing OCRs
        // SOQL Query 3
        Set<Id> existingOcrIds = new Set<Id>();
        for (OpportunityContactRole ocr : ocrMap.values()) {
            existingOcrIds.add(ocr.Id);
        }

        Map<Id, npsp__Partial_Soft_Credit__c> pscMap = new Map<Id, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact_Role__c, npsp__Amount__c, npsp__Role__c 
            FROM npsp__Partial_Soft_Credit__c 
            WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact_Role__c IN :existingOcrIds
        ]) {
            pscMap.put(psc.npsp__Contact_Role__c, psc);
        }

        // 4. Prepare OCRs for Upsert
        Map<String, OpportunityContactRole> ocrsToUpsertMap = new Map<String, OpportunityContactRole>();
        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + '-' + req.contactId;
            OpportunityContactRole ocr = ocrMap.get(key);

            if (ocr != null) {
                // Update existing role
                ocr.Role = req.role;
                ocrsToUpsertMap.put(key, ocr);
            } else {
                // Create new role
                ocr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
                ocrsToUpsertMap.put(key, ocr);
            }
        }

        // DML 1: Upsert OCRs
        if (!ocrsToUpsertMap.isEmpty()) {
            upsert ocrsToUpsertMap.values();
        }

        // 5. Prepare Partial Soft Credits for Upsert
        List<npsp__Partial_Soft_Credit__c> pscsToUpsert = new List<npsp__Partial_Soft_Credit__c>();
        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + '-' + req.contactId;
            // The OCR in the upsert map now contains its Id
            OpportunityContactRole ocr = ocrsToUpsertMap.get(key);

            // Check if a PSC already exists for this specific OCR
            npsp__Partial_Soft_Credit__c psc = pscMap.get(ocr.Id);
            if (psc != null) {
                // Update existing PSC
                psc.npsp__Amount__c = req.amount;
                psc.npsp__Role__c = req.role;
                pscsToUpsert.add(psc);
            } else {
                // Create new PSC
                psc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact_Role__c = ocr.Id,
                    npsp__Amount__c = req.amount,
                    npsp__Role__c = req.role
                );
                pscsToUpsert.add(psc);
            }
        }

        // DML 2: Upsert PSCs
        if (!pscsToUpsert.isEmpty()) {
            upsert pscsToUpsert;
        }
    }
}
