/**
 * @description TDTM Trigger Handler for Opportunity to create follow-up tasks for major gifts.
 * This class follows the NPSP Table-Driven Trigger Management (TDTM) pattern.
 */
public class OPP_MajorGiftFollowUp_TDTM implements npsp.TDTM_TriggerHandler {

    /**
     * @description Main entry point for the TDTM dispatcher.
     * @param list1 The list of new records (Trigger.new).
     * @param list2 The list of old records (Trigger.old).
     * @param map1 The map of new records (Trigger.newMap).
     * @param map2 The map of old records (Trigger.oldMap).
     */
    public void run(List<SObject> list1, List<SObject> list2, Map<String, SObject> map1, Map<String, SObject> map2) {
        List<Task> tasksToCreate = new List<Task>();

        for (SObject so : list1) {
            Opportunity opp = (Opportunity)so;

            // Define the criteria for a "Major Gift"
            // 1. Stage is Closed Won
            // 2. Amount is 5000 or more
            Boolean isCurrentMajor = opp.StageName == 'Closed Won' && 
                                     opp.Amount != null && 
                                     opp.Amount >= 5000;

            // Determine if the record was already a major gift in the previous state (for updates)
            Boolean wasMajor = false;
            if (list2 != null && !list2.isEmpty() && map2 != null && map2.containsKey(opp.Id)) {
                Opportunity oldOpp = (Opportunity)map2.get(opp.Id);
                if (oldOpp != null) {
                    wasMajor = oldOpp.StageName == 'Closed Won' && 
                               oldOpp.Amount != null && 
                               oldOpp.Amount >= 5000;
                }
            }

            // We only want to create a task if the opportunity JUST became a major gift.
            // This prevents duplicate tasks if an existing major gift is edited.
            if (isCurrentMajor && !wasMajor) {
                tasksToCreate.add(new Task(
                    Subject = 'Major gift thank-you call',
                    Priority = 'High',
                    Status = 'Not Started',
                    WhatId = opp.Id,
                    WhoId = opp.npsp__Primary_Contact__c,
                    OwnerId = opp.OwnerId,
                    ActivityDate = opp.CloseDate != null ? opp.CloseDate.addDays(3) : null
                ));
            }
        }

        // Perform a single DML statement for all tasks to ensure bulk-safety and efficiency
        if (!tasksToCreate.isEmpty()) {
            insert tasksToCreate;
        }
    }
}
