public class TA_Account_CreateOnboardingTask implements TAF.TriggerAction {
    /**
     * TA_Account_CreateOnboardingTask
     * 
     * This action creates an onboarding Task for the Account Owner when a new Account
     * is created with specific Customer Types.
     */
    public void execute(List<SObject> newList, Map<Id, SObject> oldMap, TAF.TriggerContext context) {
        // Only process on insertion (creation)
        if (context.isInsert()) {
            List<Task> tasksToInsert = new List<Task>();

            for (SObject so : newList) {
                Account acc = (Account)so;

                // Filter by Account Type
                if (acc.Type == 'Customer - Direct' || acc.Type == 'Customer - Channel') {
                    tasksToInsert.add(new Task(
                        Subject = 'Onboard new customer',
                        WhatId = acc.Id,
                        OwnerId = acc.OwnerId,
                        ActivityDate = Date.today().addDays(7),
                        Status = 'Not Started',
                        Priority = 'Normal'
                    ));
                }
            }

            // Perform a single DML statement only if tasks were generated
            if (!tasksToInsert.isEmpty()) {
                insert tasksToInsert;
            }
        }
    }
}
