```apex
public class AccountOwnershipService {
    /**
     * Reassigns the owner of the specified Accounts and all their related Contacts.
     * Bypasses Account trigger actions using TAF to avoid expensive territory recalculations.
     * 
     * @param accountIds Set of Account IDs to be reassigned.
     * @param newOwnerId The ID of the new owner.
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        try {
            // Use TAF's transaction bypass for the whole Account sObject to avoid expensive automation
            TAF.setBypass(Account.SObjectType, true);

            // Prepare Account updates
            List<Account> accountsToUpdate = new List<Account>();
            for (Id accId : accountIds) {
                accountsToUpdate.add(new Account(
                    Id = accId, 
                    OwnerId = newOwnerId
                ));
            }
            // Perform all-or-none DML on Accounts
            update accountsToUpdate;

            // Prepare Contact updates
            // Querying related contacts allows us to update them in a single bulk DML statement
            List<Contact> contactsToUpdate = [SELECT Id FROM Contact WHERE AccountId IN :accountIds];
            for (Contact con : contactsToUpdate) {
                con.OwnerId = newOwnerId;
            }
            // Perform all-or-none DML on Contacts (Contact trigger actions will run normally)
            if (!contactsToUpdate.isEmpty()) {
                update contactsToUpdate;
            }

        } finally {
            // Ensure Account automation is restored for the remainder of the transaction,
            // regardless of whether the update succeeded or failed.
            TAF.setBypass(Account.SObjectType, false);
        }
    }
}
```

