public with sharing class TA_Opportunity_CollectForErpSync implements TriggerAction {
    public static Set<Id> idsToSync = new Set<Id>();

    public void execute(TriggerContext context) {
        if (context.getTriggerType() == TriggerType.AfterInsert) {
            for (Opportunity opp : (List<Opportunity>) context.getNew()) {
                idsToSync.add(opp.Id);
            }
        } else if (context.getTriggerType() == TriggerType.AfterUpdate) {
            Map<Id, Opportunity> oldMap = context.getOldMap();
            for (Opportunity opp : (List<Opportunity>) context.getNew()) {
                if (opp.StageName != oldMap.get(opp.Id).StageName) {
                    idsToSync.add(opp.Id);
                }
            }
        }
    }
}
