public class TA_Contact_PreventDuplicateEmail implements TA_Action {
    public void execute(TA_ActionContext context) {
        List<Contact> newList = context.getNew();
        Map<Id, Contact> oldMap = context.getOldMap();
        List<Contact> candidates = new List<Contact>();

        // 1. Identify candidate records that need checking
        for (Contact c : newList) {
            // Rule: Contacts without an Account or without an Email are not checked
            if (c.AccountId == null || c.Email == null) {
                continue;
            }

            if (oldMap == null) {
                // Before Insert context
                candidates.add(c);
            } else {
                // Before Update context
                Contact oldC = oldMap.get(c.Id);
                // Rule: Only check if Email or AccountId changed (avoids blocking legacy duplicates)
                if (c.AccountId != oldC.AccountId || c.Email != oldC.Email) {
                    candidates.add(c);
                }
            }
        }

        if (candidates.isEmpty()) {
            return;
        }

        // 2. Prepare data for bulk SOQL query
        Set<Id> accountIds = new Set<Id>();
        Set<String> allEmails = new Set<String>();
        for (Contact c : candidates) {
            accountIds.add(c.AccountId);
            allEmails.add(c.Email);
        }

        // 3. Single SOQL query to find existing contacts matching the criteria
        List<Contact> existing = [
            SELECT Id, AccountId, Email 
            FROM Contact 
            WHERE AccountId IN :accountIds 
            AND Email IN :allEmails
        ];

        // 4. Map existing contacts to a lookup key: AccountId|email(lowercase)
        // We must exclude contacts that are currently being updated to avoid "self-conflict"
        Set<String> existingKeys = new Set<String>();
        Set<Id> updatedIds = (oldMap != null) ? oldMap.keySet() : new Set<Id>();

        for (Contact ex : existing) {
            if (!updatedIds.contains(ex.Id)) {
                existingKeys.add(ex.AccountId + '|' + ex.Email.toLowerCase());
            }
        }

        // 5. Validate candidates against existing records and other records in the same transaction
        // Rule: Within a single save, the first one in the list is accepted, others rejected.
        Set<String> transactionKeys = new Set<String>();
        for (Contact c : candidates) {
            String key = c.AccountId + '|' + c.Email.toLowerCase();

            if (existingKeys.contains(key) || transactionKeys.contains(key)) {
                c.addError('Another contact on this account already uses this email address.');
            } else {
                // This contact is valid (for now), so we "claim" this combination for this transaction
                transactionKeys.add(key);
            }
        }
    }
}
