public class TA_Lead_NormalizeContactInfo {
    /**
     * TAF Action to normalize Lead contact information.
     * Performs cleaning on Email, Company, and LeadSource.
     * 
     * @param leads The list of Leads from the trigger context.
     */
    public void run(List<Lead> leads) {
        for (Lead l : leads) {
            // Email: leading/trailing whitespace removed and lower-cased.
            // A null email stays null.
            if (l.Email != null) {
                l.Email = l.Email.trim().toLowerCase();
            }

            // Company: leading/trailing whitespace removed.
            if (l.Company != null) {
                l.Company = l.Company.trim();
            }

            // LeadSource: set to 'Web' when blank; an existing value is kept.
            if (String.isBlank(l.LeadSource)) {
                l.LeadSource = 'Web';
            }
        }
    }
}
