public class TA_Contact_Queries {
    private static TA_Contact_Queries instance;
    public Map<Id, Account> accountsById { get; private set; }

    private TA_Contact_Queries() {
        this.accountsById = new Map<Id, Account>();
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    public class Service implements TAF_Action {
        public void execute(List<SObject> records) {
            Set<Id> accountIds = new Set<Id>();
            for (SObject so : records) {
                Contact c = (Contact)so;
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }

            if (!accountIds.isEmpty()) {
                Map<Id, Account> queriedAccounts = new Map<Id, Account>([
                    SELECT Id, BillingStreet, BillingCity, BillingPostalCode, BillingCountry, AccountSource 
                    FROM Account 
                    WHERE Id IN :accountIds
                ]);
                TA_Contact_Queries.getInstance().accountsById.putAll(queriedAccounts);
            }
        }
    }
}
